import * as https from "node:https";
function main(): void {
  const a: any = https.globalAgent;
  console.log(a.scheduling, a.agentKeepAliveTimeoutBuffer, a.maxCachedSessions, a.keepAlive);
  const o = a.options;
  console.log(o.defaultPort, o.protocol, o.noDelay, o.scheduling, o.timeout, o.path, o.keepAlive);
  console.log(https.createServer.length, https.get.length);
}
